session_start(); require_once __DIR__ . '/../lead-engine/config.php';
if(empty($_SESSION['mp_dashboard_auth'])){header('Location:/dashboard/');exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sbq($ep){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json'],CURLOPT_TIMEOUT=>25]);$b=curl_exec($ch);curl_close($ch);$d=json_decode($b,true);return is_array($d)?$d:[];}
$rows=sbq('prospector_opportunities?select=*&order=opportunity_score.desc,created_at.desc&limit=150');
?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="/dashboard/assets/goliath-ui.css?v=36"><title>Prospector Opportunities</title></head><body><div class="g-shell"><?php require __DIR__.'/includes/goliath-sidebar-v34.php'; ?><main class="g-main"><section class="g-top"><div><h1>Prospector Opportunities</h1><p>FSBO, foreclosure, owner/contact and seller opportunity mining.</p></div></section><section class="g-panel"><h2>Review Queue <span><?=count($rows)?></span></h2><div class="g-tableWrap"><table class="g-stealthTable"><thead><tr><th>Score</th><th>Owner / Property</th><th>Contact</th><th>Source</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=h($r['opportunity_score']??0)?></td><td><div class='g-name'><?=h($r['owner_name']?:'Unknown Owner')?></div><div class='g-subtle'><?=h(($r['address']??'').' · '.($r['town']??''))?></div></td><td><?=h(($r['phone']?:'Phone needed').' · '.($r['email']?:'Email needed'))?></td><td><?=h($r['source_name']??'')?></td><td><?=h($r['recommended_action']??'Review')?></td></tr><?php endforeach;?></tbody></table></div></section></main></div></body></html>